#include <algorithm>
#include <charconv>
#include <format>
#include <map>
#include <optional>
#include <string>
#include <variant>
#include <vector>

class Tweakables
{
public:
    void addInt(const std::string& name, int* value, int min, int max) { m_entries[name] = IntEntry{ value, min, max }; }
    void addFloat(const std::string& name, float* value, float min, float max) { m_entries[name] = FloatEntry{ value, min, max }; }
    void addBool(const std::string& name, bool* value) { m_entries[name] = BoolEntry{ value }; }

    std::string set(const std::string& name, const std::string& text)
    {
        const auto found{ m_entries.find(name) };
        if (found == m_entries.end()) return "unknown: " + name;
        Entry& e{ found->second };
        if (auto* i{ std::get_if<IntEntry>(&e) })
        {
            int v{ 0 };
            const auto [end, err] = std::from_chars(text.data(), text.data() + text.size(), v);
            if (err != std::errc{} || end != text.data() + text.size() || text.empty()) return "bad value: " + text;
            *i->value = std::clamp(v, i->min, i->max);
        }
        else if (auto* f{ std::get_if<FloatEntry>(&e) })
        {
            float v{ 0 };
            const auto [end, err] = std::from_chars(text.data(), text.data() + text.size(), v);
            if (err != std::errc{} || end != text.data() + text.size() || text.empty()) return "bad value: " + text;
            *f->value = std::clamp(v, f->min, f->max);
        }
        else
        {
            auto& b{ std::get<BoolEntry>(e) };
            if (text == "true" || text == "1" || text == "on") *b.value = true;
            else if (text == "false" || text == "0" || text == "off") *b.value = false;
            else return "bad value: " + text;
        }
        return name + " = " + *get(name);
    }

    std::optional<std::string> get(const std::string& name) const
    {
        const auto found{ m_entries.find(name) };
        if (found == m_entries.end()) return std::nullopt;
        const Entry& e{ found->second };
        if (const auto* i{ std::get_if<IntEntry>(&e) }) return std::to_string(*i->value);
        if (const auto* f{ std::get_if<FloatEntry>(&e) }) return std::format("{}", *f->value);
        return std::string(*std::get<BoolEntry>(e).value ? "true" : "false");
    }

    std::vector<std::string> names() const
    {
        std::vector<std::string> out;
        for (const auto& [name, entry] : m_entries) out.push_back(name);
        return out;
    }

private:
    struct IntEntry { int* value; int min; int max; };
    struct FloatEntry { float* value; float min; float max; };
    struct BoolEntry { bool* value; };
    using Entry = std::variant<IntEntry, FloatEntry, BoolEntry>;
    std::map<std::string, Entry> m_entries;
};

hints:
`std::from_chars` (from `<charconv>`) parses a number from a range of characters and reports where it stopped; the whole text was a number only if it stopped at the end without an error:

```cpp
int v{};
const char* end{ text.data() + text.size() };
const auto [stop, error]{ std::from_chars(text.data(), end, v) };
const bool ok{ error == std::errc{} && stop == end };
```

The same call works for a `float`.

