TEST("the example")
{
    Tweakables t; int sight{ 8 };
    t.addInt("monster.sight", &sight, 1, 30);
    CHECK_EQ(t.set("monster.sight", "50"), std::string("monster.sight = 30"));
    CHECK_EQ(sight, 30);
    CHECK_EQ(t.set("monster.sight", "lots"), std::string("bad value: lots"));
    CHECK_EQ(sight, 30);
}
TEST("clamped at the bottom too") { Tweakables t; int v{ 5 }; t.addInt("v", &v, 1, 10); t.set("v", "-4"); CHECK_EQ(v, 1); }
TEST("floats") { Tweakables t; float s{ 0.12f }; t.addFloat("player.slide", &s, 0.0f, 0.5f); CHECK_EQ(t.set("player.slide", "0.25"), std::string("player.slide = 0.25")); CHECK_NEAR(s, 0.25, 1e-6); t.set("player.slide", "9"); CHECK_NEAR(s, 0.5, 1e-6); }
TEST("booleans") { Tweakables t; bool god{ false }; t.addBool("cheat.god", &god); CHECK_EQ(t.set("cheat.god", "on"), std::string("cheat.god = true")); CHECK(god); t.set("cheat.god", "0"); CHECK(!god); CHECK_EQ(t.set("cheat.god", "maybe"), std::string("bad value: maybe")); }
TEST("unknown names") { Tweakables t; CHECK_EQ(t.set("nope", "1"), std::string("unknown: nope")); CHECK(!t.get("nope").has_value()); }
TEST("partial numbers are refused") { Tweakables t; int v{ 3 }; t.addInt("v", &v, 0, 100); CHECK_EQ(t.set("v", "12abc"), std::string("bad value: 12abc")); CHECK_EQ(t.set("v", ""), std::string("bad value: ")); CHECK_EQ(v, 3); }
TEST("names are sorted") { Tweakables t; int a{ 0 }, b{ 0 }; bool c{ false }; t.addInt("z.last", &a, 0, 1); t.addBool("a.first", &c); t.addInt("m.mid", &b, 0, 1); CHECK(t.names() == std::vector<std::string>({ "a.first", "m.mid", "z.last" })); }
TEST("get reads the live variable") { Tweakables t; int v{ 7 }; t.addInt("v", &v, 0, 10); v = 9; CHECK_EQ(*t.get("v"), std::string("9")); }

